#!/bin/bash
# usage: hreach.sh "x,y[,h] ..." fromx fromy [fromh] — human-nav path from a cell to each cell, with path length
S=/tmp/claude-1000/-mnt-e-ShadowTactics/707807bc-a0d1-48d2-80ab-faf908724265/scratchpad/tools
pts=$(echo "$1" | sed 's/ /;/g')
bash $S/ev.sh "var f=new UnityEngine.AI.NavMeshQueryFilter{agentTypeID=Vespertine.Core.NavAreas.HumanAgent, areaMask=Vespertine.Core.NavAreas.HumanMask}; UnityEngine.AI.NavMeshHit h0; UnityEngine.AI.NavMesh.SamplePosition(L.Grid.CellCenter($2,$3)+UnityEngine.Vector3.up*${4:-0}f, out h0, 1.6f, f); var s=\"from=\"+h0.position.y.ToString(\"0.0\")+\" \"; foreach (var t in \"$pts\".Split(';')) { var q=t.Split(','); UnityEngine.AI.NavMeshHit h; string r=\"n\"; if (UnityEngine.AI.NavMesh.SamplePosition(L.Grid.CellCenter(int.Parse(q[0]),int.Parse(q[1]))+UnityEngine.Vector3.up*(q.Length>2?float.Parse(q[2]):0f), out h, 1.6f, f)) { var p=new UnityEngine.AI.NavMeshPath(); if (UnityEngine.AI.NavMesh.CalculatePath(h0.position,h.position,f,p)&&p.status==UnityEngine.AI.NavMeshPathStatus.PathComplete) { float d=0; for (int i=1;i<p.corners.Length;i++) d+=UnityEngine.Vector3.Distance(p.corners[i-1],p.corners[i]); r=\"Y\"+d.ToString(\"0\"); } } else r=\"nomesh\"; s+=t+\"=\"+r+\" \"; } return s;"
